selected_yaml:
jobs:
  oidc:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v2
      - name: Login to Azure
        uses: azure/login@v1
        with:
          client-id: ${{ secrets.AZURE_CLIENT_ID }}
          tenant-id: ${{ secrets.AZURE_TENANT_ID }}
          subscription-id: ${{ secrets.AZURE_SUBSCRIPTION_ID }}
          federated-credentials: ${{ secrets.AZURE_FEDERATED_CREDENTIALS }}

jobs:
  example_job:
    concurrency:
      group: ${{ github.workflow }}-${{ github.ref }}
      cancel-in-progress: ${{ !startsWith(github.ref, 'refs/heads/release/') }}

on:
  issues:
    types: [assigned]

jobs:
  move-issue:
    runs-on: ubuntu-latest
    steps:
      - name: Move issue to project
        uses: actions/checkout@v2
      - name: Update project
        uses: actions/github-script@v6
        with:
          script: |
            const projectNumber = 1; // Replace with your project number
            const columnName = 'In Progress'; // Replace with your column name
            const issue = context.payload.issue;
            const project = await github.projects.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo
            }).then(res => res.data.find(p => p.number === projectNumber));
            if (!project) {
              throw new Error(`Project not found: ${projectNumber}`);
            }
            const columns = await github.projects.listColumns({
              project_id: project.id
            }).then(res => res.data);
            const column = columns.find(c => c.name === columnName);
            if (!column) {
              throw new Error(`Column not found: ${columnName}`);
            }
            await github.projects.createCard({
              column_id: column.id,
              content_id: issue.id,
              content_type: 'Issue'
            });

jobs:
  request-jwt:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v2

      - name: Request JWT
        uses: actions/github-script@v6
        with:
          script: |
            const core = require('@actions/core');
            const { getIDToken } = require('@actions/core/lib/id-token');
            async function run() {
              try {
                const idToken = await getIDToken();
                console.log(`ID Token: ${idToken}`);
              } catch (error) {
                core.setFailed(`Error retrieving ID token: ${error.message}`);
              }
            }
            run();

concurrency:
  group: ${{ github.head_ref || github.run_id }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' }}

jobs:
  evaluate-expressions:
    runs-on: ubuntu-latest
    steps:
      - name: Evaluate boolean
        run: echo ${{ true && false }}
      - name: Evaluate null
        run: echo ${{ null || true }}
      - name: Evaluate number
        run: echo ${{ 0 || 1 }}
      - name: Evaluate string
        run: echo ${{ '' || 'default' }}

jobs:
  deploy:
    runs-on: ubuntu-latest
    steps:
    - name: Checkout
      uses: actions/checkout@v2

    - name: Log in to Amazon ECR
      id: login-ecr
      uses: aws-actions/amazon-ecr-login@v1

    - name: Build, tag, and push image to Amazon ECR
      env:
        ECR_REGISTRY: ${{ secrets.ECR_REGISTRY }}
        ECR_REPOSITORY: ${{ secrets.ECR_REPOSITORY }}
        IMAGE_TAG: ${{ github.sha }}
      run: |
        docker build -t $ECR_REGISTRY/$ECR_REPOSITORY:$IMAGE_TAG .
        docker push $ECR_REGISTRY/$ECR_REPOSITORY:$IMAGE_TAG

    - name: Update ECS service with new image
      env:
        AWS_REGION: ${{ secrets.AWS_REGION }}
        ECS_CLUSTER: ${{ secrets.ECS_CLUSTER }}
        ECS_SERVICE: ${{ secrets.ECS_SERVICE }}
        CONTAINER_NAME: ${{ secrets.CONTAINER_NAME }}
        ECR_REGISTRY: ${{ secrets.ECR_REGISTRY }}
        ECR_REPOSITORY: ${{ secrets.ECR_REPOSITORY }}
        IMAGE_TAG: ${{ github.sha }}
      run: |
        aws ecs update-service --cluster $ECS_CLUSTER --service $ECS_SERVICE --force-new-deployment --region $AWS_REGION

concurrency:
  group: ${{ github.ref }}
  cancel-in-progress: true

jobs:
  example_job:
    concurrency:
      group: ${{ github.head_ref || github.run_id }}
      cancel-in-progress: ${{ github.event_name == 'pull_request' }}

